import {useCallback,useEffect,useMemo,useState} from 'react'
import {Archive,ArrowDownUp,CalendarDays,Check,CheckCircle2,ChevronLeft,ChevronRight,Clock,Download,FileText,Filter,HandHeart,House,Inbox,LayoutList,Menu,MoreHorizontal,Paperclip,Plus,Search,Settings,Share2,Trash2,Upload,Users,X,AlertCircle,Repeat,Briefcase,Heart,MapPin,CalendarCheck,Circle,Edit3,Copy,Folder,ShoppingBag,ClipboardList,MessageCircle} from 'lucide-react'
import {db} from './db/db'
import type {Activity,Attachment,Category,Contact,Favor,Section,Status,Subtask,NeededData,Reminder,ReminderFrequency} from './types'
import {dateLabel,daysLeft,download,id,isLate,isOpen,progress,statusLabel,today} from './services/utils'
import {createAttachmentKey,decryptAttachment,encryptAttachment,unlockAttachmentKey,type AttachmentCryptoConfig} from './services/attachment-crypto'
const defaultCategories:Category[]=[{id:'c1',name:'Xestións e trámites',color:'#4389DC',icon:'ClipboardList'},{id:'c2',name:'Documentación',color:'#7770DB',icon:'FileText'},{id:'c3',name:'Consultas e información',color:'#39BFA5',icon:'MessageCircle'},{id:'c4',name:'Compras e recados',color:'#F4B942',icon:'ShoppingBag'},{id:'c5',name:'Traballo',color:'#4389DC',icon:'Briefcase'},{id:'c6',name:'Familia',color:'#F46B62',icon:'Heart'},{id:'c7',name:'Amizades',color:'#39BFA5',icon:'Users'},{id:'c8',name:'Outros',color:'#918F8A',icon:'Folder'}]
const nav:{id:Section;label:string;icon:any}[]=[{id:'home',label:'Inicio',icon:House},{id:'favores',label:'Favores',icon:LayoutList},{id:'calendar',label:'Calendario',icon:CalendarDays},{id:'archive',label:'Arquivo',icon:Archive}]
const blank=():Favor=>({id:id(),title:'',person:'',scope:'Persoal',category:'Outros',requested:today(),due:'',priority:'Normal',status:'pending',notes:'',subtasks:[],needed:[],created:new Date().toISOString(),updated:new Date().toISOString(),reminders:[]})
export default function App(){
 const[categories,setCategories]=useState<Category[]>(defaultCategories),[favors,setFavors]=useState<Favor[]>([]),[activity,setActivity]=useState<Activity[]>([]),[contacts,setContacts]=useState<Contact[]>([]),[files,setFiles]=useState<Attachment[]>([]),[cryptoConfig,setCryptoConfig]=useState<AttachmentCryptoConfig|null>(null),[cryptoKey,setCryptoKey]=useState<CryptoKey|null>(null),[section,setSection]=useState<Section>('home'),[selected,setSelected]=useState<string|null>(null),[modal,setModal]=useState<'new'|'edit'|'settings'|null>(null),[draft,setDraft]=useState<Favor>(blank),[query,setQuery]=useState(''),[filter,setFilter]=useState('Todos'),[sort,setSort]=useState('Prazo máis próximo'),[menu,setMenu]=useState(false),[month,setMonth]=useState(new Date()),[calDate,setCalDate]=useState(today()),[searchOn,setSearchOn]=useState(false),[toast,setToast]=useState('')
 const refresh=useCallback(async()=>{const[a,b,c,storedCats,storedCrypto]=await Promise.all([db.favors.toArray(),db.contacts.toArray(),db.attachments.toArray(),db.settings.get('categories'),db.settings.get('attachmentCrypto')]);setFavors(a);setContacts(b);setFiles(c);setCryptoConfig(storedCrypto?.value as AttachmentCryptoConfig||null);setCategories(Array.isArray(storedCats?.value)&&storedCats.value.length?storedCats.value as Category[]:defaultCategories)},[])
 useEffect(()=>{refresh()},[refresh]);useEffect(()=>{if(selected)db.activity.where('favorId').equals(selected).reverse().sortBy('at').then(rows=>setActivity(rows))},[selected,favors]);useEffect(()=>{const h=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='n'){e.preventDefault();openNew()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='f'){e.preventDefault();setSearchOn(true);document.getElementById('search-input')?.focus()}if(e.key==='Escape'){setModal(null);setSelected(null)}};window.addEventListener('keydown',h);return()=>window.removeEventListener('keydown',h)})
 const say=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(''),2600)}
 function openNew(){setDraft(blank());setModal('new')}
 function edit(f:Favor){setDraft(structuredClone(f));setModal('edit')}
 async function save(){if(!draft.title.trim()||!draft.person.trim()){say('Engade o favor e quen cho pediu.');return}const next={...draft,updated:new Date().toISOString()};await db.favors.put(next);await db.activity.put({id:id(),favorId:next.id,text:modal==='new'?'Favor creado':'Favor actualizado',at:new Date().toISOString()});if(!contacts.some(c=>c.name.toLowerCase()===next.person.trim().toLowerCase()))await db.contacts.put({id:id(),name:next.person.trim()});setModal(null);await refresh();setSelected(next.id);say('Gardado correctamente')}
 async function patchFavor(f:Favor,patch:Partial<Favor>){const events:string[]=[];if('due'in patch&&patch.due!==f.due)events.push('Data límite actualizada');if(patch.subtasks){const before=f.subtasks||[],after=patch.subtasks;if(after.length>before.length)events.push('Subtarefa engadida');else if(after.length<before.length)events.push('Subtarefa eliminada');else if(after.filter(x=>x.done).length!==before.filter(x=>x.done).length)events.push('Estado dunha subtarefa actualizado')}if(patch.needed){const before=f.needed||[],after=patch.needed;if(after.length>before.length)events.push('Dato necesario engadido');else if(after.length<before.length)events.push('Dato necesario eliminado');else if(after.filter(x=>x.received).length!==before.filter(x=>x.received).length)events.push('Recepción dun dato actualizada')}await db.transaction('rw',db.favors,db.activity,async()=>{await db.favors.update(f.id,{...patch,updated:new Date().toISOString()});for(const text of events)await db.activity.put({id:id(),favorId:f.id,text,at:new Date().toISOString()})});await refresh()}
 async function enableAttachmentEncryption(password:string){const result=await createAttachmentKey(password);await db.settings.put({key:'attachmentCrypto',value:result.config});setCryptoConfig(result.config);setCryptoKey(result.key);say('Cifrado de anexos activado neste dispositivo')}
 async function unlockAttachments(password:string){if(!cryptoConfig)throw new Error('Configura primeiro o cifrado');const key=await unlockAttachmentKey(password,cryptoConfig);setCryptoKey(key);say('Anexos desbloqueados')}
 async function encryptExistingAttachments(){if(!cryptoKey||!cryptoConfig)throw new Error('Desbloquea primeiro os anexos');const all=await db.attachments.toArray();for(const file of all){if(file.encrypted)continue;const encrypted=await encryptAttachment(file.blob,cryptoKey);await db.attachments.update(file.id,{blob:encrypted.blob,iv:encrypted.iv,encrypted:true})}await refresh();say('Anexos existentes cifrados')}
 async function downloadAttachment(file:Attachment){try{if(file.encrypted){if(!cryptoKey)throw new Error('Desbloquea os anexos en Configuración para abrilos');if(!file.iv)throw new Error('Falta información de cifrado para este anexo');download(file.name,await decryptAttachment(file.blob,file.iv,cryptoKey,file.type))}else download(file.name,file.blob)}catch(e){say(e instanceof Error?e.message:'Non se puido abrir o anexo')}}
 async function remove(f:Favor){if(!confirm(`Eliminar «${f.title}» e os seus anexos? Esta acción non se pode desfacer.`))return;await db.transaction('rw',db.favors,db.attachments,db.activity,async()=>{await db.favors.delete(f.id);await db.attachments.where('favorId').equals(f.id).delete();await db.activity.where('favorId').equals(f.id).delete()});setSelected(null);refresh();say('Favor eliminado')}
 async function status(f:Favor,s:Status){const completed=s==='done'?new Date().toISOString():s==='archived'?f.completed:undefined;await db.favors.put({...f,status:s,completed,reminders:(s==='done'||s==='archived')?f.reminders.map(r=>r.state==='scheduled'?{...r,state:'cancelled'}:r):f.reminders,updated:new Date().toISOString()});await db.activity.put({id:id(),favorId:f.id,text:s==='done'?'Favor finalizado':s==='archived'?'Favor arquivado':f.status==='archived'?'Favor recuperado':s==='pending'&&f.status==='done'?'Favor reaberto':`Estado: ${statusLabel(s)}`,at:new Date().toISOString()});refresh();say(s==='done'?'Favor finalizado':s==='pending'?'Favor reaberto':'Estado actualizado')}
 const active=favors.filter(isOpen),late=active.filter(isLate),todayList=active.filter(f=>f.due===today()||isLate(f)),soon=active.filter(f=>!isLate(f)&&daysLeft(f)<=7&&daysLeft(f)>=1).sort((a,b)=>a.due.localeCompare(b.due)),completed=favors.filter(f=>f.status==='done'||f.status==='archived')
 const shown=useMemo(()=>{let a=favors.filter(f=>section==='archive'?['done','archived'].includes(f.status):section==='favores'?f.status!=='archived':true);if(query.trim()){const q=query.toLowerCase();a=a.filter(f=>[f.title,f.person,f.category,f.scope,f.notes].some(x=>x.toLowerCase().includes(q)))}if(section==='favores'&&filter!=='Todos'){a=a.filter(f=>filter==='Atrasados'?isLate(f):filter==='Persoais'?f.scope==='Persoal':filter==='Profesionais'?f.scope==='Profesional':f.status===({Pendentes:'pending','En curso':'doing',Agardando:'waiting',Finalizados:'done'} as any)[filter])}if(section==='archive'&&filter!=='Todos')a=a.filter(f=>filter==='Finalizados'?f.status==='done':f.status==='archived');return a.sort((x,y)=>sort==='Prioridade'?['Urxente','Alta','Normal','Baixa'].indexOf(x.priority)-['Urxente','Alta','Normal','Baixa'].indexOf(y.priority):sort==='Máis atrasados'?x.due.localeCompare(y.due):sort==='Data de creación'?y.created.localeCompare(x.created):sort==='Nome da persoa'?x.person.localeCompare(y.person):((x.due||'9999').localeCompare(y.due||'9999')))},[favors,section,query,filter,sort])
 const focus=favors.find(x=>x.id===selected)
 const title=section==='home'?'Bos días':section==='favores'?'Os teus favores':section==='calendar'?'Calendario':section==='archive'?'Arquivo':'Configuración'
 async function backup(){const data={app:'FAVORES',version:2,exportedAt:new Date().toISOString(),favors:await db.favors.toArray(),contacts:await db.contacts.toArray(),categories:(await db.settings.get('categories'))?.value||defaultCategories,activity:await db.activity.toArray()};download(`favores-transferencia-${today()}.json`,new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));say('Ficheiro listo para transferir')}
 async function importBackup(file:File){try{const data=JSON.parse(await file.text());if((data.app&&data.app!=='FAVORES')||!Array.isArray(data.favors)||![1,2].includes(data.version)||!data.favors.every((f:any)=>f&&typeof f.id==='string'&&typeof f.title==='string'&&typeof f.person==='string'))throw Error();if(data.contacts!==undefined&&(!Array.isArray(data.contacts)||!data.contacts.every((c:any)=>c&&typeof c.id==='string'&&typeof c.name==='string')))throw Error();if(data.activity!==undefined&&(!Array.isArray(data.activity)||!data.activity.every((a:any)=>a&&typeof a.id==='string'&&typeof a.favorId==='string'&&typeof a.at==='string')))throw Error();const existing=new Set(await db.favors.toCollection().primaryKeys()),matches=data.favors.filter((f:Favor)=>existing.has(f.id)).length;if(!confirm(`Importar ${data.favors.length} favores e fusionar os datos? ${matches} xa existen neste dispositivo e actualizaranse cos valores do ficheiro. Os demais conservaranse.`))return;await db.transaction('rw',db.favors,db.contacts,db.settings,db.activity,async()=>{await db.favors.bulkPut(data.favors);if(Array.isArray(data.contacts))await db.contacts.bulkPut(data.contacts);if(Array.isArray(data.activity))await db.activity.bulkPut(data.activity);if(Array.isArray(data.categories)&&data.categories.every((c:any)=>c&&typeof c.id==='string'&&typeof c.name==='string'&&/^#[0-9a-f]{6}$/i.test(c.color)&&typeof c.icon==='string'))await db.settings.put({key:'categories',value:data.categories})});await refresh();say('Datos fusionados')}catch{say('O ficheiro non é unha transferencia válida de Favores')}}
 async function attach(f:Favor,fileList:FileList|null){if(!fileList)return;if(cryptoConfig&&!cryptoKey){say('Desbloquea o cifrado en Configuración antes de engadir anexos');return}for(const file of Array.from(fileList)){const encrypted=cryptoConfig&&cryptoKey?await encryptAttachment(file,cryptoKey):null;await db.attachments.put({id:id(),favorId:f.id,name:file.name,type:file.type,size:file.size,added:new Date().toISOString(),blob:encrypted?.blob||file,encrypted:!!encrypted,iv:encrypted?.iv})}refresh();say('Documento anexado')}
 async function duplicate(f:Favor){const n={...structuredClone(f),id:id(),title:`${f.title} (copia)`,status:'pending' as Status,created:new Date().toISOString(),updated:new Date().toISOString(),completed:undefined,reminders:[]};await db.favors.put(n);await db.activity.put({id:id(),favorId:n.id,text:'Favor duplicado',at:new Date().toISOString()});refresh();setSelected(n.id);say('Copia creada sen documentos nin avisos')}
 const view=()=>{
 if(section==='home')return <><div className="welcome"><div><span className="eyebrow">{new Intl.DateTimeFormat('gl-ES',{weekday:'long',day:'numeric',month:'long'}).format(new Date()).toUpperCase()}</span><h2>O importante,<br/><em>sen esquecementos.</em></h2><p>Os compromisos de hoxe, nun só lugar.</p></div><div className="welcome-art"><div className="art-circle"><HandHeart size={42}/><Check className="art-check" size={20}/></div><span className="spark s1">✦</span><span className="spark s2">✧</span></div></div><div className="metrics"><Metric label="Pendentes" value={active.filter(x=>x.status==='pending').length} color="coral" icon={Inbox}/><Metric label="En curso" value={active.filter(x=>x.status==='doing').length} color="blue" icon={Repeat}/><Metric label="Atrasados" value={late.length} color="rose" icon={AlertCircle}/><Metric label="Para hoxe" value={active.filter(x=>x.due===today()).length} color="gold" icon={Clock}/><Metric label="Finalizados este mes" value={completed.filter(x=>x.completed&&new Date(x.completed).getMonth()===new Date().getMonth()&&new Date(x.completed).getFullYear()===new Date().getFullYear()).length} color="teal" icon={CheckCircle2}/></div><div className="section-head"><div><span className="eyebrow">O MÁIS URXENTE</span><h3>Para hoxe <span className="count-bubble">{todayList.length}</span></h3></div><button className="text-btn" onClick={()=>{setSection('favores');setFilter('Atrasados')}}>Ver todos <ChevronRight size={16}/></button></div>{todayList.length?<div className="card-list">{todayList.map(f=><FavorCard key={f.id} f={f} categories={categories} onClick={()=>setSelected(f.id)} onDone={()=>status(f,'done')}/>)}</div>:<Empty icon={CheckCircle2} title="Todo ao día" text="Non tes prazos para hoxe. Aproveita o respiro."/>}<div className="section-head next-head"><div><span className="eyebrow">VAI PREPARANDO</span><h3>Próximos días</h3></div><span className="muted">7 días</span></div>{soon.length?<div className="card-list two-col">{soon.slice(0,4).map(f=><FavorCard key={f.id} f={f} categories={categories} onClick={()=>setSelected(f.id)} onDone={()=>status(f,'done')}/>)}</div>:<Empty icon={CalendarCheck} title="Sen datas próximas" text="Os novos compromisos aparecerán aquí."/>}</>
 if(section==='calendar')return <><div className="month-bar"><div><span className="eyebrow">VISTA MENSUAL</span><h2>{new Intl.DateTimeFormat('gl-ES',{month:'long',year:'numeric'}).format(month)}</h2></div><div className="month-arrows"><button onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))}><ChevronLeft/></button><button onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}><ChevronRight/></button></div></div><div className="calendar"><div className="weekdays">{['Lun','Mar','Mér','Xov','Ven','Sáb','Dom'].map(x=><span key={x}>{x}</span>)}</div><div className="days">{Array.from({length:42},(_,i)=>{const first=new Date(month.getFullYear(),month.getMonth(),1),offset=(first.getDay()+6)%7,d=new Date(month.getFullYear(),month.getMonth(),i-offset+1),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,fs=favors.filter(f=>f.due===key&&f.status!=='archived'),inside=d.getMonth()===month.getMonth();return <button key={key} className={`day ${inside?'':'outside'} ${key===today()?'is-today':''}`} onClick={()=>{setCalDate(key);setSelected(fs.length===1?fs[0].id:null);if(!fs.length)say('Non hai favores con prazo este día')}}><span>{d.getDate()}</span>{fs.slice(0,2).map((f,j)=><i key={j} className={`dot ${f.priority==='Urxente'?'urgent':f.priority==='Alta'?'high':''}`}/>)}</button>})}</div></div><div className="section-head"><div><span className="eyebrow">DATA SELECCIONADA</span><h3>{dateLabel(calDate)}</h3></div></div><div className="card-list">{favors.filter(f=>f.due===calDate&&f.status!=='archived').map(f=><FavorCard key={f.id} f={f} categories={categories} onClick={()=>setSelected(f.id)} onDone={()=>status(f,'done')}/>)}</div></>
 if(section==='settings')return <SettingsView categories={categories} onSaveCategories={async(next:Category[])=>{await db.settings.put({key:'categories',value:next});await refresh()}} contacts={contacts} files={files} cryptoConfig={cryptoConfig} cryptoUnlocked={!!cryptoKey} onSetupEncryption={enableAttachmentEncryption} onUnlockEncryption={unlockAttachments} onLockEncryption={()=>{setCryptoKey(null);say('Anexos bloqueados')}} onEncryptExisting={encryptExistingAttachments} onBackup={backup} onImport={importBackup} onRefresh={refresh} say={say}/>
 return <><div className="filters"><div className="filter-scroll">{(section==='archive'?['Todos','Finalizados','Arquivados']:['Todos','Pendentes','En curso','Agardando','Atrasados','Persoais','Profesionais']).map(x=><button key={x} onClick={()=>setFilter(x)} className={`pill ${filter===x?'active':''}`}>{x}</button>)}</div><label className="sort-select"><ArrowDownUp size={15}/><select value={sort} onChange={e=>setSort(e.target.value)}><option>Prazo máis próximo</option><option>Máis atrasados</option><option>Prioridade</option><option>Data de creación</option><option>Nome da persoa</option></select></label></div>{shown.length?<div className="card-list">{shown.map(f=><FavorCard key={f.id} f={f} categories={categories} onClick={()=>setSelected(f.id)} onDone={()=>status(f,'done')} onMenu={()=>setSelected(f.id)}/>)}</div>:<Empty icon={section==='archive'?Archive:Inbox} title={section==='archive'?'O arquivo está baleiro':'Aínda non hai favores'} text={section==='archive'?'Os compromisos finalizados aparecerán aquí.':'Engade o primeiro encargo que che pidan.'} action={section==='favores'?openNew:undefined}/>}</>
 }
 return <div className="app-shell"><aside className="sidebar"><div className="brand"><div className="brand-mark"><HandHeart size={22}/></div><div><strong>favores</strong><small>unha man amiga</small></div></div><button className="new-btn" onClick={openNew}><Plus size={18}/> Novo favor <kbd>⌘ N</kbd></button><div className="side-label">MENÚ</div><nav>{nav.map(n=><button key={n.id} className={section===n.id?'selected':''} onClick={()=>{setSection(n.id);setFilter('Todos')}}><n.icon size={19}/><span>{n.label}</span>{n.id==='favores'&&active.length>0&&<b>{active.length}</b>}</button>)}</nav><div className="sidebar-bottom"><button onClick={()=>setSection('settings')} className={section==='settings'?'selected':''}><Settings size={19}/><span>Configuración</span></button><div className="privacy-note"><div className="privacy-icon"><Check size={14}/></div><div><strong>Os teus datos, contigo</strong><p>Gardados só neste dispositivo.</p></div></div><span className="version">FAVORES · VERSIÓN 1.0</span></div></aside><div className="main-area"><header className="topbar"><button className="mobile-brand" onClick={()=>setSection('home')}><div className="brand-mark"><HandHeart size={20}/></div><strong>favores</strong></button><div className="breadcrumb"><span>O teu espazo</span><ChevronRight size={14}/><strong>{section==='settings'?'Configuración':nav.find(x=>x.id===section)?.label}</strong></div><div className="top-actions">{searchOn?<div className="searchbox"><Search size={17}/><input id="search-input" placeholder="Buscar favores…" value={query} onChange={e=>setQuery(e.target.value)} autoFocus/><button onClick={()=>{setQuery('');setSearchOn(false)}}><X size={16}/></button></div>:<button className="icon-btn" title="Buscar" onClick={()=>{setSearchOn(true);setTimeout(()=>document.getElementById('search-input')?.focus(),0)}}><Search size={19}/></button>}<button className="avatar" onClick={()=>setSection('settings')}>M</button></div></header><main className="content"><div className="page-title"><div><span className="eyebrow">O TEU ESPAZO PERSOAL</span><h1>{title}</h1></div>{section!=='home'&&section!=='calendar'&&section!=='settings'&&<button className="primary-btn" onClick={openNew}><Plus size={17}/> Novo favor</button>}</div>{view()}</main></div><button className="mobile-fab" onClick={openNew}><Plus size={25}/></button><nav className="mobile-nav">{nav.map(n=><button key={n.id} onClick={()=>setSection(n.id)} className={section===n.id?'current':''}><n.icon size={20}/><span>{n.label}</span></button>)}</nav>
 {focus&&<div className="drawer-backdrop" onClick={()=>setSelected(null)}><aside className="detail-drawer" onClick={e=>e.stopPropagation()}><div className="drawer-top"><button className="icon-btn" onClick={()=>setSelected(null)}><X/></button><div className="drawer-actions"><button className="icon-btn" title="Compartir resumo" onClick={()=>shareSummary(focus,say)}><Share2 size={18}/></button><button className="icon-btn" title="Duplicar" onClick={()=>duplicate(focus)}><Copy size={17}/></button><button className="icon-btn danger" title="Eliminar" onClick={()=>remove(focus)}><Trash2 size={18}/></button></div></div><div className="detail-scroll"><InlineFavorFields categories={categories} favor={focus} onChange={(patch:Partial<Favor>)=>patchFavor(focus,patch)} onStatus={(next:Status)=>status(focus,next)} late={isLate(focus)}/><div className="detail-section"><InlineSubtasks favor={focus} onChange={(patch:Partial<Favor>)=>patchFavor(focus,patch)}/></div><div className="detail-section"><InlineNeeded favor={focus} onChange={(patch:Partial<Favor>)=>patchFavor(focus,patch)}/></div><div className="detail-section"><div className="section-title"><h3>Notas</h3><span className="inline-hint">Gardado ao escribir</span></div><textarea className="inline-notes" aria-label="Notas do favor" placeholder="Engade notas…" value={focus.notes} onChange={e=>patchFavor(focus,{notes:e.target.value})}/></div><div className="detail-section"><div className="section-title"><h3>Documentos</h3><label className="attach-btn"><Plus size={15}/> Engadir<input type="file" multiple onChange={e=>attach(focus,e.target.files)}/></label></div>{files.filter(x=>x.favorId===focus.id).map(a=><div className="file-row" key={a.id}><FileText size={18}/><span><b>{a.name}</b><small>{(a.size/1024).toFixed(0)} KB · {a.encrypted?'AES-GCM cifrado':'sen cifrar'}</small></span><button aria-label={`Abrir ${a.name}`} onClick={()=>downloadAttachment(a)}><Download size={17}/></button><button onClick={async()=>{if(confirm('Eliminar definitivamente este anexo?')){await db.attachments.delete(a.id);refresh()}}}><Trash2 size={16}/></button></div>)}{!files.some(x=>x.favorId===focus.id)&&<p className="muted">Anexos gardados localmente neste dispositivo.</p>}<p className="security-hint">{cryptoConfig?(cryptoKey?'Os anexos novos e os xa cifrados están protexidos con AES-GCM neste dispositivo.':'Cifrado activo e bloqueado: desbloquea en Configuración para engadir ou abrir anexos.'):'Os anexos aínda non están cifrados. Activa o cifrado en Configuración antes de gardar documentos sensibles.'}</p></div><div className="detail-section"><div className="section-title"><h3>Actividade recente</h3></div>{activity.length?activity.slice(0,8).map(item=><div className="activity-row" key={item.id}><i/><span>{item.text}<small>{new Intl.DateTimeFormat('gl-ES',{dateStyle:'medium',timeStyle:'short'}).format(new Date(item.at))}</small></span></div>):<p className="inline-hint">A actividade deste favor aparecerá aquí.</p>}</div><div className="detail-section"><ReminderEditor favor={focus} onSave={async (reminders:Reminder[])=>{await db.favors.put({...focus,reminders:[...focus.reminders,...reminders],updated:new Date().toISOString()});await refresh();say(reminders.length>1?`${reminders.length} recordatorios gardados`:'Recordatorio gardado')}} onReschedule={async (reminder:Reminder)=>{await db.favors.put({...focus,reminders:focus.reminders.map(x=>x.id===reminder.id?reminder:x),updated:new Date().toISOString()});await refresh();say('Recordatorio actualizado')}} onCancel={async (reminder:Reminder)=>{await db.favors.put({...focus,reminders:focus.reminders.map(x=>x.id===reminder.id?{...x,state:'cancelled'}:x),updated:new Date().toISOString()});await refresh();say('Recordatorio eliminado')}}/></div><button className="secondary-btn archive-action" onClick={()=>status(focus,focus.status==='archived'?'pending':'archived')}><Archive size={16}/>{focus.status==='archived'?'Recuperar do arquivo':'Arquivar favor'}</button><button className={`finish-btn ${focus.status==='done'?'reopen':''}`} onClick={()=>status(focus,focus.status==='done'?'pending':'done')}>{focus.status==='done'?<><Repeat size={17}/> Reabrir favor</>:<><CheckCircle2 size={17}/> Finalizar favor</>}</button></div></aside></div>}
 {modal&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(null)}}><form className="form-modal" onSubmit={e=>{e.preventDefault();save()}}><div className="modal-head"><div><span className="eyebrow">{modal==='new'?'ENGADIR COMPROMISO':'ACTUALIZAR INFORMACIÓN'}</span><h2>{modal==='new'?'Novo favor':'Editar favor'}</h2></div><button type="button" className="icon-btn" onClick={()=>setModal(null)}><X/></button></div><label className="field full"><span>Que favor che pediron? *</span><input autoFocus value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})} placeholder="Ex. Levar os documentos á xestoría" required/></label><label className="field full"><span>Quen cho pediu? *</span><input list="contact-list" value={draft.person} onChange={e=>setDraft({...draft,person:e.target.value})} placeholder="Nome da persoa" required/><datalist id="contact-list">{contacts.map(c=><option key={c.id} value={c.name}/>)}</datalist></label><div className="field-grid"><label className="field"><span>Para cando?</span><input type="date" value={draft.due} onChange={e=>setDraft({...draft,due:e.target.value})}/></label><label className="field"><span>Hora (opcional)</span><input type="time" value={draft.dueTime||''} onChange={e=>setDraft({...draft,dueTime:e.target.value})}/></label><label className="field"><span>Ámbito</span><select value={draft.scope} onChange={e=>setDraft({...draft,scope:e.target.value as Favor['scope']})}><option>Persoal</option><option>Profesional</option><option>Outros</option></select></label><label className="field"><span>Categoría</span><select value={draft.category} onChange={e=>setDraft({...draft,category:e.target.value})}>{categories.map((c:Category)=><option key={c.id}>{c.name}</option>)}</select></label><label className="field"><span>Prioridade</span><select value={draft.priority} onChange={e=>setDraft({...draft,priority:e.target.value as Favor['priority']})}>{['Baixa','Normal','Alta','Urxente'].map(c=><option key={c}>{c}</option>)}</select></label><label className="field"><span>Estado</span><select value={draft.status} onChange={e=>setDraft({...draft,status:e.target.value as Status})}><option value="pending">Pendente</option><option value="doing">En curso</option><option value="waiting">Agardando</option></select></label></div><label className="field full"><span>Notas</span><textarea rows={2} value={draft.notes} onChange={e=>setDraft({...draft,notes:e.target.value})} placeholder="Detalles que che axuden a lembrar…"/></label><div className="detail-section form-section"><div className="section-title"><h3>Subtarefas <small>{draft.subtasks.length}</small></h3><button type="button" onClick={()=>setDraft({...draft,subtasks:[...draft.subtasks,{id:id(),text:'',done:false}]})}><Plus size={15}/> Engadir</button></div>{draft.subtasks.map((t,i)=><div className="editable-row" key={t.id}><input placeholder="Que hai que facer?" value={t.text} onChange={e=>{const a=[...draft.subtasks];a[i]={...t,text:e.target.value};setDraft({...draft,subtasks:a})}}/><button type="button" onClick={()=>setDraft({...draft,subtasks:draft.subtasks.filter(x=>x.id!==t.id)})}><X size={16}/></button></div>)}</div><div className="detail-section form-section"><div className="section-title"><h3>Datos que necesito <small>{draft.needed.length}</small></h3><button type="button" onClick={()=>setDraft({...draft,needed:[...draft.needed,{id:id(),text:'',received:false}]})}><Plus size={15}/> Engadir</button></div>{draft.needed.map((n,i)=><div className="editable-row" key={n.id}><input placeholder="Ex. Número de expediente" value={n.text} onChange={e=>{const a=[...draft.needed];a[i]={...n,text:e.target.value};setDraft({...draft,needed:a})}}/><button type="button" onClick={()=>setDraft({...draft,needed:draft.needed.filter(x=>x.id!==n.id)})}><X size={16}/></button></div>)}</div><div className="modal-footer"><span>* Campos obrigatorios</span><button type="button" className="secondary-btn" onClick={()=>setModal(null)}>Cancelar</button><button className="primary-btn" type="submit"><Check size={17}/> Gardar favor</button></div></form></div>}
 {toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}</div>}</div>
}
function Metric({label,value,color,icon:Icon}:any){return <div className={`metric ${color}`}><div className="metric-icon"><Icon size={18}/></div><span className="metric-value">{value}</span><span className="metric-label">{label}</span></div>}
function Progress({f}:{f:Favor}){return <div className="progress-track"><i style={{width:`${progress(f)}%`}}/></div>}
function FavorCard({f,onClick,onDone,categories}:any){const cat=(categories||defaultCategories).find((x:Category)=>x.name===f.category)||defaultCategories[7];return <article className="favor-card" onClick={onClick}><div className={`card-accent ${f.priority==='Urxente'?'urgent':f.priority==='Alta'?'high':f.scope==='Profesional'?'work':''}`}/><div className="card-main"><div className="card-top"><div className="category-line"><span className="category-icon" style={{background:`${cat.color}22`,color:cat.color}}><CategoryGlyph name={cat.icon} size={14}/></span><span>{f.category}</span></div><button className="more-btn" onClick={e=>{e.stopPropagation();onClick()}}><MoreHorizontal size={18}/></button></div><h3>{f.title}</h3><p className="requester"><Users size={14}/>{f.person}</p><div className="card-bottom"><div className={`due ${isLate(f)?'late':''}`}><CalendarDays size={14}/>{isLate(f)?`Atrasado · ${dateLabel(f.due)}`:dateLabel(f.due)}</div><span className={`status-chip ${f.status}`}>{statusLabel(f.status)}</span>{f.subtasks.length>0&&<span className="task-progress">{f.subtasks.filter((x:any)=>x.done).length}/{f.subtasks.length} <Check size={13}/></span>}<button className="quick-done" title="Finalizar" onClick={e=>{e.stopPropagation();onDone()}}><Check size={16}/></button></div></div></article>}
function Empty({icon:Icon,title,text,action}:any){return <div className="empty"><div className="empty-icon"><Icon size={26}/></div><h3>{title}</h3><p>{text}</p>{action&&<button className="primary-btn" onClick={action}><Plus size={16}/> Novo favor</button>}</div>}
function InlineFavorFields({favor:f,onChange,onStatus,late,categories}:any){return <div className="inline-favor-fields"><span className={`status-chip ${f.status} ${late?'late-chip':''}`}>{late?'Atrasado':statusLabel(f.status)}</span><input className="inline-title" aria-label="Título do favor" value={f.title} onChange={e=>onChange({title:e.target.value})}/><label className="inline-person"><Users size={16}/><input aria-label="Persoa solicitante" value={f.person} onChange={e=>onChange({person:e.target.value})}/></label><div className="inline-meta-grid"><label className="inline-field"><span>Prazo</span><input type="date" value={f.due||''} onChange={e=>onChange({due:e.target.value})}/></label><label className="inline-field"><span>Hora límite</span><input type="time" value={f.dueTime||''} onChange={e=>onChange({dueTime:e.target.value})}/></label><label className="inline-field"><span>Solicitado</span><input type="date" value={f.requested||''} onChange={e=>onChange({requested:e.target.value})}/></label><label className="inline-field"><span>Estado</span><select value={f.status} onChange={e=>onStatus(e.target.value as Status)}><option value="pending">Pendente</option><option value="doing">En curso</option><option value="waiting">Agardando</option><option value="done">Finalizado</option><option value="archived">Arquivado</option></select></label><label className="inline-field"><span>Ámbito</span><select value={f.scope} onChange={e=>onChange({scope:e.target.value})}><option>Persoal</option><option>Profesional</option><option>Outros</option></select></label><label className="inline-field"><span>Categoría</span><select value={f.category} onChange={e=>onChange({category:e.target.value})}>{categories.map((c:Category)=><option key={c.id}>{c.name}</option>)}</select></label><label className="inline-field"><span>Prioridade</span><select value={f.priority} onChange={e=>onChange({priority:e.target.value})}>{['Baixa','Normal','Alta','Urxente'].map((c:string)=><option key={c}>{c}</option>)}</select></label></div></div>}
function InlineSubtasks({favor:f,onChange}:any){const tasks=f.subtasks||[];function update(next:any[]){onChange({subtasks:next})}return <><div className="section-title"><h3>Subtarefas <small>{progress(f)}%</small></h3><button onClick={()=>update([...tasks,{id:id(),text:'',done:false}])}><Plus size={15}/> Engadir</button></div>{tasks.map((t:any,i:number)=><div className="inline-task-row" key={t.id} draggable onDragStart={e=>{e.dataTransfer.setData('text/plain',String(i));e.dataTransfer.effectAllowed='move'}} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const from=Number(e.dataTransfer.getData('text/plain'));if(Number.isNaN(from)||from===i)return;const a=[...tasks],moved=a.splice(from,1)[0];a.splice(i,0,moved);update(a)}}><input aria-label="Subtarefa" placeholder="Escribe unha tarefa…" value={t.text} onChange={e=>{const a=[...tasks];a[i]={...t,text:e.target.value};update(a)}}/><input type="date" aria-label="Prazo da subtarefa" value={t.due||''} onChange={e=>{const a=[...tasks];a[i]={...t,due:e.target.value};update(a)}}/><label className="inline-check"><input type="checkbox" checked={t.done} onChange={e=>{const a=[...tasks];a[i]={...t,done:e.target.checked};update(a)}}/><span>{t.done?'Feita':'Pendente'}</span></label><button className="remove-inline" aria-label="Eliminar subtarefa" onClick={()=>update(tasks.filter((x:any)=>x.id!==t.id))}><Trash2 size={15}/></button></div>)}{!tasks.length&&<p className="inline-hint">Engade aquí as tarefas que completan este favor.</p>}<Progress f={f}/></>}
function InlineNeeded({favor:f,onChange}:any){const items=f.needed||[];function update(next:any[]){onChange({needed:next})}return <><div className="section-title"><h3>Datos que necesito <small>{items.filter((x:any)=>!x.received).length} pendentes</small></h3><button onClick={()=>update([...items,{id:id(),text:'',received:false}])}><Plus size={15}/> Engadir</button></div>{items.map((n:any,i:number)=><div className="inline-needed-row" key={n.id}><input type="checkbox" aria-label="Dato recibido" checked={n.received} onChange={e=>{const a=[...items];a[i]={...n,received:e.target.checked};update(a)}}/><div><input className="needed-text" placeholder="Que información necesitas?" value={n.text} onChange={e=>{const a=[...items];a[i]={...n,text:e.target.value};update(a)}}/><input className="needed-note" placeholder="Nota opcional" value={n.note||''} onChange={e=>{const a=[...items];a[i]={...n,note:e.target.value};update(a)}}/></div><button className="remove-inline" aria-label="Eliminar dato" onClick={()=>update(items.filter((x:any)=>x.id!==n.id))}><Trash2 size={15}/></button></div>)}{!items.length&&<p className="inline-hint">Engade datos pendentes e márcaos cando os recibas.</p>}</>}

function ReminderEditor({favor,onSave,onCancel,onReschedule}:any){
 const[when,setWhen]=useState(''),[frequency,setFrequency]=useState<ReminderFrequency|'none'>('none'),[count,setCount]=useState(5),[busy,setBusy]=useState(false),[editing,setEditing]=useState<string|null>(null),[error,setError]=useState('')
 function toLocalInput(date:Date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}T${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`}
 function quick(minutesBefore:number){if(!favor.due){setError('Engade primeiro un prazo ao favor');return}const base=new Date(`${favor.due}T${favor.dueTime||'09:00'}`);base.setMinutes(base.getMinutes()-minutesBefore);if(base.getTime()<=Date.now()){setError('Ese recordatorio xa pasou; escolle unha hora futura');return}setError('');setEditing(null);setWhen(toLocalInput(base))}
 function nextDate(start:Date,step:number,repeat:ReminderFrequency){const result=new Date(start);if(repeat==='daily')result.setDate(result.getDate()+step);else if(repeat==='weekly')result.setDate(result.getDate()+7*step);else{const day=result.getDate();result.setDate(1);result.setMonth(result.getMonth()+step);const last=new Date(result.getFullYear(),result.getMonth()+1,0).getDate();result.setDate(Math.min(day,last))}return result}
 async function submit(){if(!when)return;const start=new Date(when);if(!Number.isFinite(start.getTime())||start.getTime()<=Date.now()){setError('Escolle unha data futura');return}setBusy(true);setError('');try{if(editing){const current=favor.reminders.find((r:Reminder)=>r.id===editing);if(!current)throw new Error('O recordatorio xa non existe');await onReschedule({...current,dueAt:start.toISOString(),state:'scheduled'});setEditing(null)}else{const total=frequency==='none'?1:Math.max(2,Math.min(52,count));const seriesId=id();const reminders=Array.from({length:total},(_,i)=>({id:id(),dueAt:nextDate(start,i,frequency==='none'?'daily':frequency).toISOString(),state:'scheduled' as const,created:new Date().toISOString(),seriesId,sequence:i+1,seriesTotal:total,frequency:frequency==='none'?undefined:frequency}));const existing=new Set(favor.reminders.filter((r:Reminder)=>r.state==='scheduled').map((r:Reminder)=>r.dueAt));if(reminders.some(r=>existing.has(r.dueAt))){setError('Xa tes un recordatorio programado nesa data e hora');return}await onSave(reminders)}setWhen('');setFrequency('none')}catch(e){setError(e instanceof Error?e.message:'Non se puido gardar o recordatorio')}finally{setBusy(false)}}
 function editReminder(r:Reminder){setEditing(r.id);setWhen(toLocalInput(new Date(r.dueAt)));setFrequency('none');setError('')}
 return <><div className="section-title"><h3>Recordatorios <small>{favor.reminders.filter((r:Reminder)=>r.state==='scheduled').length} gardados</small></h3></div><p className="muted">Estas datas quedan anotadas na ficha. Nesta versión non se envían avisos coa aplicación pechada.</p>{favor.reminders.map((r:Reminder)=><div className="reminder-row" key={r.id}><Clock size={15}/><span>{new Intl.DateTimeFormat('gl-ES',{dateStyle:'medium',timeStyle:'short'}).format(new Date(r.dueAt))}{r.seriesTotal&&r.seriesTotal>1&&<em>{({daily:'Diario',weekly:'Semanal',monthly:'Mensual'} as any)[r.frequency||'daily']} · {r.sequence}/{r.seriesTotal}</em>}<small>{r.state==='scheduled'?'Gardado na ficha':r.state==='cancelled'?'Cancelado':r.state==='sent'?'Enviado':'Erro'}</small></span>{r.state==='scheduled'&&<><button aria-label="Editar recordatorio" onClick={()=>editReminder(r)}><Edit3 size={15}/></button><button aria-label="Eliminar recordatorio" onClick={()=>onCancel(r)}><X size={16}/></button></>}</div>)}
 <div className="quick-reminders">{[['Unha semana antes',10080],['Tres días antes',4320],['Un día antes',1440],['O propio día',0],['Unha hora antes',60]].map(([label,mins]:any)=><button type="button" key={label} onClick={()=>quick(mins)}>{label}</button>)}</div>
 <div className="add-reminder"><input aria-label="Data e hora do recordatorio" type="datetime-local" min={toLocalInput(new Date(Date.now()+60000))} value={when} onChange={e=>{setWhen(e.target.value);setError('')}}/><button className="secondary-btn" disabled={!when||busy} onClick={submit}><Plus size={15}/>{editing?'Actualizar':frequency==='none'?'Gardar data':'Gardar repetición'}</button></div>
 {editing&&<button className="reminder-cancel-edit" onClick={()=>{setEditing(null);setWhen('')}}>Cancelar edición</button>}
 {!editing&&<div className="repeat-controls"><label>Repetición<select value={frequency} onChange={e=>setFrequency(e.target.value as ReminderFrequency|'none')}><option value="none">Non repetir</option><option value="daily">Diaria</option><option value="weekly">Semanal</option><option value="monthly">Mensual</option></select></label>{frequency!=='none'&&<label>Número de avisos (2–52)<input type="number" min={2} max={52} value={count} onChange={e=>setCount(Math.max(2,Math.min(52,Number(e.target.value)||2)))}/></label>}</div>}
 {error&&<p className="push-error">{error}</p>}<p className="muted">As repeticións crean como máximo 52 datas gardadas na ficha; non son notificacións do sistema.</p></>
}
function EncryptionSettings({config,unlocked,plainCount,onSetup,onUnlock,onLock,onEncryptExisting,say}:any){const[password,setPassword]=useState(''),[confirmPassword,setConfirmPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{if(config)await onUnlock(password);else{if(password.length<12)throw new Error('Usa un contrasinal de polo menos 12 caracteres');if(password!==confirmPassword)throw new Error('Os contrasinais non coinciden');await onSetup(password)}setPassword('');setConfirmPassword('')}catch(e){setError(e instanceof Error?e.message:'Non se puido configurar o cifrado')}finally{setBusy(false)}}async function encryptPlain(){setBusy(true);setError('');try{await onEncryptExisting()}catch(e){setError(e instanceof Error?e.message:'Non se puideron cifrar os anexos')}finally{setBusy(false)}}return <section className="settings-card encryption-card"><div className="settings-icon teal-bg"><Check/></div><div><h3>Cifrado dos anexos</h3><p>{config?'AES-GCM de 256 bits; a chave derívase do teu contrasinal con PBKDF2-SHA-256. A chave existe só na memoria mentres está desbloqueado.':'Activa o cifrado local antes de gardar documentación sensible. O contrasinal non se garda nin se envía.'}</p><div className={`push-status ${config?'crypto-on':''}`}>{!config?'Desactivado':unlocked?'Activo e desbloqueado':'Activo e bloqueado'}</div>{config&&plainCount>0&&<p className="security-hint">Hai {plainCount} anexo(s) sen cifrar. Desbloquea e cifra os existentes para protexelos.</p>}{config&&plainCount===0&&<p className="inline-hint">Todos os anexos gardados están cifrados.</p>}{error&&<p className="push-error">{error}</p>}</div>{!config||!unlocked?<form className="encryption-form" onSubmit={submit}><input type="password" autoComplete="new-password" minLength={12} required placeholder={config?'Contrasinal de cifrado':'Escolle un contrasinal (12+ caracteres)'} value={password} onChange={e=>setPassword(e.target.value)}/>{!config&&<input type="password" autoComplete="new-password" minLength={12} required placeholder="Repite o contrasinal" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)}/>}<button type="submit" className="secondary-btn" disabled={busy}>{busy?'Agarda…':config?'Desbloquear':'Activar cifrado'}</button></form>:<div className="settings-actions">{plainCount>0&&<button className="secondary-btn" disabled={busy} onClick={encryptPlain}>{busy?'Cifrando…':'Cifrar anexos existentes'}</button>}<button className="secondary-btn" disabled={busy} onClick={onLock}>Bloquear agora</button></div>}<p className="crypto-warning">Se esqueces o contrasinal, os anexos cifrados non se poden recuperar. Exportar a copia JSON non inclúe anexos. O cifrado protexe o contido, non os nomes nin tamaños dos ficheiros.</p></section>}
function CategoryGlyph({name,size=16}:any){const icons:any={Folder,FileText,ShoppingBag,ClipboardList,MessageCircle,Briefcase,Heart,Users};const Icon=icons[name]||Folder;return <Icon size={size}/>}
async function shareSummary(f:Favor,say:(message:string)=>void){const text=[f.title,`Solicitou: ${f.person}`,`Prazo: ${f.due?dateLabel(f.due):'Sen prazo'}`,`Estado: ${statusLabel(f.status)}`,`Prioridade: ${f.priority}`,`Ámbito: ${f.scope} · ${f.category}`].filter(Boolean).join('\n');try{if(navigator.share){await navigator.share({title:f.title,text});return}if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);say('Resumo copiado');return}}catch(e){if(e instanceof Error&&e.name==='AbortError')return}download(`resumo-${f.id}.txt`,new Blob([text],{type:'text/plain;charset=utf-8'}));say('Resumo descargado')}
function CategorySettings({categories,onSave,say}:any){const[name,setName]=useState(''),[color,setColor]=useState('#F46B62'),[icon,setIcon]=useState('Folder');async function add(){const n=name.trim();if(!n)return;if(categories.some((c:Category)=>c.name.toLocaleLowerCase()===n.toLocaleLowerCase())){say('Xa existe unha categoría con ese nome');return}await onSave([...categories,{id:id(),name:n,color,icon}]);setName('');say('Categoría engadida')}async function update(item:Category,patch:Partial<Category>){if('name'in patch){const clean=patch.name?.trim();if(!clean){say('A categoría precisa un nome');return}patch={...patch,name:clean}}if(patch.name&&patch.name!==item.name){if(categories.some((c:Category)=>c.id!==item.id&&c.name.toLocaleLowerCase()===patch.name!.toLocaleLowerCase())){say('Xa existe unha categoría con ese nome');return}await db.favors.where('category').equals(item.name).modify({category:patch.name})}await onSave(categories.map((c:Category)=>c.id===item.id?{...c,...patch}:c))}return <section className="settings-card"><div className="settings-icon violet-bg"><Folder/></div><div><h3>Categorías</h3><p>Personaliza categorías propias. As predefinidas sempre están dispoñibles.</p></div><div className="category-add"><input placeholder="Nome da categoría" value={name} onChange={e=>setName(e.target.value)}/><input aria-label="Cor da categoría" type="color" value={color} onChange={e=>setColor(e.target.value)}/><select aria-label="Icona da categoría" value={icon} onChange={e=>setIcon(e.target.value)}>{['Folder','FileText','ShoppingBag','ClipboardList','MessageCircle','Briefcase','Heart','Users'].map(x=><option key={x}>{x}</option>)}</select><button className="secondary-btn" disabled={!name.trim()} onClick={add}><Plus size={15}/> Engadir</button></div><div className="category-list">{categories.map((c:Category)=><div className="category-row" key={c.id}><span className="category-icon" style={{background:`${c.color}22`,color:c.color}}><CategoryGlyph name={c.icon}/></span><input aria-label="Nome da categoría" value={c.name} onChange={e=>update(c,{name:e.target.value})}/><input aria-label={`Cor de ${c.name}`} type="color" value={c.color} onChange={e=>update(c,{color:e.target.value})}/><select aria-label={`Icona de ${c.name}`} value={c.icon} onChange={e=>update(c,{icon:e.target.value})}>{['Folder','FileText','ShoppingBag','ClipboardList','MessageCircle','Briefcase','Heart','Users'].map(x=><option key={x}>{x}</option>)}</select>{c.id.startsWith('c')?<span className="built-in-label">Predefinida</span>:<button className="remove-inline" aria-label={`Eliminar ${c.name}`} onClick={async()=>{const count=await db.favors.where('category').equals(c.name).count();if(count){say('Esta categoría está asociada a favores. Cambia a súa categoría antes de eliminala.');return}if(confirm(`Eliminar a categoría «${c.name}»?`))await onSave(categories.filter((x:Category)=>x.id!==c.id))}}><Trash2 size={15}/></button>}</div>)}</div></section>}
function SettingsView({contacts,onBackup,onImport,onRefresh,say,categories,onSaveCategories,files,cryptoConfig,cryptoUnlocked,onSetupEncryption,onUnlockEncryption,onLockEncryption,onEncryptExisting}:any){
 const[contactOpen,setContactOpen]=useState(false),[editing,setEditing]=useState<string|null>(null),[draft,setDraft]=useState<Contact>({id:'',name:'',organization:'',phone:'',email:'',notes:''}),[allContacts,setAllContacts]=useState<Contact[]>(contacts)
 useEffect(()=>setAllContacts(contacts),[contacts])
 function beginNew(){setEditing(null);setDraft({id:'',name:'',organization:'',phone:'',email:'',notes:''});setContactOpen(true)}
 function beginEdit(c:Contact){setEditing(c.id);setDraft({...c});setContactOpen(true)}
 async function saveContact(e:React.FormEvent){e.preventDefault();if(!draft.name.trim())return;await db.contacts.put({...draft,id:editing||id(),name:draft.name.trim(),organization:draft.organization?.trim(),phone:draft.phone?.trim(),email:draft.email?.trim(),notes:draft.notes?.trim()});setContactOpen(false);setEditing(null);onRefresh();say(editing?'Contacto actualizado':'Contacto gardado')}
 return <div className="settings-grid">
  <section className="settings-card"><div className="settings-icon coral-bg"><Download/></div><div><h3>Transferencia manual entre dispositivos</h3><p>Exporta un JSON neste dispositivo, pásao por Arquivos/iCloud Drive ou AirDrop e impórtao no outro. Os favores, contactos e categorías fusiónanse por identificador. Non se sincroniza só e os anexos non van no ficheiro.</p><p className="security-hint">Un rexistro co mesmo identificador actualízase cos datos importados. Garda unha copia antes de fusionar.</p></div><div className="settings-actions"><button className="secondary-btn" onClick={onBackup}><Download size={16}/> Exportar para transferir</button><label className="secondary-btn"><Upload size={16}/> Importar e fusionar<input type="file" accept="application/json,.json" hidden onChange={e=>e.target.files?.[0]&&onImport(e.target.files[0])}/></label></div></section>
  <section className="settings-card"><div className="settings-icon blue-bg"><Users/></div><div><h3>Contactos</h3><p>{allContacts.length} persoas gardadas para cubrir favores máis rápido.</p></div><button className="secondary-btn" onClick={()=>contactOpen?setContactOpen(false):beginNew()}><Plus size={16}/> Engadir contacto</button>
   {contactOpen&&<form className="contact-form" onSubmit={saveContact}><input required placeholder="Nome e apelidos" value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/><div className="contact-fields"><input placeholder="Organización ou empresa" value={draft.organization||''} onChange={e=>setDraft({...draft,organization:e.target.value})}/><input type="tel" placeholder="Teléfono" value={draft.phone||''} onChange={e=>setDraft({...draft,phone:e.target.value})}/><input type="email" placeholder="Correo electrónico" value={draft.email||''} onChange={e=>setDraft({...draft,email:e.target.value})}/><textarea placeholder="Notas" rows={2} value={draft.notes||''} onChange={e=>setDraft({...draft,notes:e.target.value})}/></div><div className="contact-form-actions"><button type="button" className="secondary-btn" onClick={()=>setContactOpen(false)}>Cancelar</button><button type="submit" className="primary-btn">{editing?'Gardar cambios':'Gardar contacto'}</button></div></form>}
   <div className="contact-list">{allContacts.map(c=><div className="contact-row" key={c.id}><div className="contact-avatar">{c.name[0]?.toUpperCase()}</div><span>{c.name}<small>{c.organization||c.email||c.phone||'Contacto persoal'}{c.email&&c.phone?` · ${c.phone}`:''}</small>{c.notes&&<small className="contact-note">{c.notes}</small>}</span><button aria-label={`Editar ${c.name}`} onClick={()=>beginEdit(c)}><Edit3 size={15}/></button><button aria-label={`Eliminar ${c.name}`} onClick={async()=>{if(confirm(`Eliminar ${c.name} dos contactos?`)){await db.contacts.delete(c.id);onRefresh()}}}><Trash2 size={15}/></button></div>)}</div>
  </section>
  <CategorySettings categories={categories} onSave={onSaveCategories} say={say}/><EncryptionSettings config={cryptoConfig} unlocked={cryptoUnlocked} plainCount={files.filter((x:Attachment)=>!x.encrypted).length} onSetup={onSetupEncryption} onUnlock={onUnlockEncryption} onLock={onLockEncryption} onEncryptExisting={onEncryptExisting} say={say}/>
  <section className="settings-card"><div className="settings-icon violet-bg"><Check/></div><div><h3>Privacidade e almacenamento</h3><p>Os datos e documentos gárdanse nesta instalación do navegador. Non se envían a ningún servidor. Se borras os datos do navegador, podes perdelos: exporta copias regularmente.</p><p className="security-hint">{cryptoConfig?'Os anexos cifrados usan AES-GCM e unha chave derivada do teu contrasinal, que non se garda. Os nomes e tamaños dos ficheiros seguen visibles localmente.':'Os anexos non están cifrados ata que actives a protección. O almacenamento local non substitúe unha bóveda cifrada para datos sensibles.'}</p></div></section>
 </div>
}
